import { NextRequest, NextResponse } from "next/server";
import { db } from "@/lib/db";
import { getSessionUser } from "@/lib/auth";
import { canConfigureSite } from "@/lib/rbac";
import type { EmailLogDTO } from "@/lib/types";

export const dynamic = "force-dynamic";

// ============================================================
// GET /api/admin/emails - the transactional-email outbox (ADMIN).
// Shows exactly what was sent to which student address, including
// the credential emails generated by account approvals.
// ============================================================

export async function GET(req: NextRequest) {
  try {
    const viewer = await getSessionUser(req);
    if (!canConfigureSite(viewer?.role)) {
      return NextResponse.json({ error: "Administrators only" }, { status: viewer ? 403 : 401 });
    }
    const kind = req.nextUrl.searchParams.get("kind")?.trim();
    const rows = await db.emailLog.findMany({
      where: kind && kind !== "ALL" ? { kind } : undefined,
      orderBy: { createdAt: "desc" },
      take: 100,
    });
    const emails: EmailLogDTO[] = rows.map((r) => ({
      id: r.id,
      to: r.to,
      subject: r.subject,
      body: r.body,
      kind: r.kind,
      status: r.status,
      createdAt: r.createdAt.toISOString(),
    }));
    return NextResponse.json({ emails });
  } catch (e) {
    console.error("GET /api/admin/emails", e);
    return NextResponse.json({ error: "Failed to load the outbox" }, { status: 500 });
  }
}
